#!/usr/bin/env node
/**
 * Prisma schema picker + mirror — the deploy-anywhere glue.
 *
 * Prisma's datasource provider is a compile-time constant, so one committed
 * schema file cannot serve both SQLite (laptop, Docker default) and Postgres
 * (Neon / Vercel). Two tracked copies exist:
 *
 *   prisma/schema.prisma             → the ACTIVE driver (committed as SQLite)
 *   prisma/schema.postgres.prisma    → the Postgres mirror, regenerated by --mirror
 *
 * Selection mode (used by postinstall / build / Docker):
 *   node scripts/pick-schema.mjs [postgres|sqlite]
 *
 *   1. explicit argv          — Docker passes its DB_SCHEMA build-arg through
 *   2. DB_SCHEMA env          — `--build-arg DB_SCHEMA=postgres`
 *   3. DATABASE_URL heuristic — postgres:// or postgresql:// → postgres
 *   4. otherwise              — leave the committed schema untouched (SQLite)
 *
 * The script only ever rewrites prisma/schema.prisma IN THE BUILD ENVIRONMENT
 * (Vercel's ephemeral container, Docker's builder stage). The committed file
 * stays SQLite so local development never depends on platform env vars.
 *
 * Mirror mode (used by humans after editing the schema):
 *   node scripts/pick-schema.mjs --mirror
 *
 *   Regenerates the INACTIVE driver file from the active one, swapping only
 *   the provider line. tests/unit/schema-parity.test.ts fails CI when the
 *   mirror drifts — run `npm run db:mirror` right after any schema change.
 */
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(process.cwd());
const active = path.join(root, "prisma", "schema.prisma");
const pgFile = path.join(root, "prisma", "schema.postgres.prisma");

const read = (f) => fs.readFileSync(f, "utf8");
const activeProvider = () => (/provider\s*=\s*"(sqlite|postgresql)"/.exec(read(active))?.[1] ?? "sqlite");

/* ---------------- mirror mode ---------------- */

if (process.argv[2] === "--mirror") {
  const prov = activeProvider();
  const body = read(active).replace(
    /provider\s*=\s*"(sqlite|postgresql)"/,
    `provider = "${prov === "sqlite" ? "postgresql" : "sqlite"}"`
  );
  if (prov === "postgresql") {
    // the active file IS the Postgres driver — refresh the SQLite mirror
    const liteBanner = [
      "// NexNotes — SQLite driver mirror (GENERATED — do not hand-edit).",
      "// Regenerate after every schema change:  npm run db:mirror",
      "",
    ].join("\n");
    const liteBody = body.replace(/^[\s\S]*?\n(?=generator)/, "");
    fs.writeFileSync(path.join(root, "prisma", "schema.sqlite.prisma"), liteBanner + liteBody);
    console.log("✓ mirrored active Postgres schema → prisma/schema.sqlite.prisma");
  } else {
    // keep the generated-file banner on top of the Postgres mirror
    const banner = [
      "// NexNotes — Postgres / Neon driver mirror (GENERATED — do not hand-edit).",
      "// Regenerate after every schema.prisma change:  npm run db:mirror",
      "// (a parity unit test fails CI when this file drifts from the active schema.)",
      "",
    ].join("\n");
    const stripped = body.replace(/^[\s\S]*?\n(?=generator)/, "");
    fs.writeFileSync(pgFile, banner + stripped);
    console.log("✓ mirrored active SQLite schema → prisma/schema.postgres.prisma");
  }
  process.exit(0);
}

/* ---------------- selection mode ---------------- */

const arg = process.argv[2];
const envSchema = process.env.DB_SCHEMA;
const dbUrl = process.env.DATABASE_URL ?? "";

let target = null;
if (arg === "postgres" || arg === "sqlite") target = arg;
else if (envSchema === "postgres" || envSchema === "sqlite") target = envSchema;
else if (/^postgres(ql)?:\/\//.test(dbUrl.trim())) target = "postgres";

if (!target) {
  console.log("→ prisma schema: committed default (SQLite) — nothing to pick");
  process.exit(0);
}

const current = activeProvider();
if (current === (target === "postgres" ? "postgresql" : "sqlite")) {
  console.log(`→ prisma schema: already ${target}`);
  process.exit(0);
}

if (target === "postgres") {
  if (!fs.existsSync(pgFile)) {
    console.error("✗ prisma/schema.postgres.prisma missing — cannot switch driver");
    process.exit(1);
  }
  fs.copyFileSync(pgFile, active);
  console.log("→ prisma schema: switched to POSTGRES (DATABASE_URL/DB_SCHEMA requested it)");
} else {
  // sqlite requested but the active file is postgres — restore from the
  // snapshot, or (snapshot not tracked yet) swap the provider line in place
  const liteFile = path.join(root, "prisma", "schema.sqlite.prisma");
  if (fs.existsSync(liteFile)) fs.copyFileSync(liteFile, active);
  else fs.writeFileSync(active, read(active).replace(/provider\s*=\s*"postgresql"/, 'provider = "sqlite"'));
  console.log("→ prisma schema: switched to SQLITE");
}
